+            const dom = this.tiles[pkey].domNode();
+            if (dom) dom.classList.remove('grouplet_grid_tab_active');
+        });
+    }
+
+    setLayout(newLayout) {
+        if (newLayout !== 'cards'
+            && newLayout !== 'tabs'
+            && newLayout !== 'vtabs') {
+            console.warn('[GG] setLayout: unknown layout', newLayout);
+            return;
+        }
